import{_ as r,o as d,c as o,a5 as e}from"./chunks/framework.R-FQ1xZ2.js";const p=JSON.parse('{"title":"L7 导览 · 进阶方向","description":"","frontmatter":{},"headers":[],"relativePath":"kb/l7-advanced/index.md","filePath":"kb/l7-advanced/index.md","lastUpdated":null}'),n={name:"kb/l7-advanced/index.md"};function a(s,t,g,l,h,i){return d(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="l7-导览-·-进阶方向" tabindex="-1">L7 导览 · 进阶方向 <a class="header-anchor" href="#l7-导览-·-进阶方向" aria-label="Permalink to &quot;L7 导览 · 进阶方向&quot;">​</a></h1><blockquote><p>本层知识点导览 ｜ <strong>10 个知识点 / 6 页正文 + 1 页导览 / 50 学时</strong> ｜ 面试频率：高 2 页、中 4 页</p></blockquote><h2 id="这一层在知识体系里的位置" tabindex="-1">这一层在知识体系里的位置 <a class="header-anchor" href="#这一层在知识体系里的位置" aria-label="Permalink to &quot;这一层在知识体系里的位置&quot;">​</a></h2><p>前六层解决的是「<strong>把模型用起来</strong>」：L0 打底、L1 讲原理、L2 会写提示词、L3 会接检索、L4 会编 Agent、L5 会上线、L6 会评测。<strong>L7 解决的是「当推理侧的招都用完了，还能动什么」</strong>——动权重（微调 / 偏好优化 / 后训练）、动成本（蒸馏 / 量化 / 调度）、动输入形态（多模态）。</p><p>一句话主干：<strong>L7 不是在讲&quot;怎么训模型&quot;，而是在讲&quot;什么时候值得训、要付什么代价、以及为什么大多数时候不该训&quot;。</strong></p><p>这一层有一个和别层不同的性质，必须提前说清：</p><blockquote><p><strong>面试权重结构是分叉的。</strong> 对于<strong>大模型开发工程师</strong>岗，<code>L7-03</code>（LoRA/QLoRA 实操）、<code>L7-04</code>（分布式全参）、<code>L7-06</code>（RL 后训练 / GRPO）、<code>L7-08</code>（推理优化）属于<strong>会被直接考到实操细节</strong>的内容；对于 <strong>AI Agent 开发 / AI 应用开发</strong>岗，这一层的定位是「<strong>能接住追问，但不用背到能实操</strong>」——面试官会问你「为什么不微调」「你没做后训练怎么保证效果」，而不是让你现写一段训练脚本。</p><p>所以本层的读法是：<strong>判据背熟、机制说清、参数不背</strong>。凡是具体参数名、默认值、模型规格（参数量 / 层数 / 上下文长度）——<strong>一律不背，一律答&quot;以官方文档为准&quot;</strong>。</p></blockquote><h2 id="本层导览-六条路" tabindex="-1">本层导览：六条路 <a class="header-anchor" href="#本层导览-六条路" aria-label="Permalink to &quot;本层导览：六条路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>知识点</th><th>一句话</th></tr></thead><tbody><tr><td><strong>① 决策</strong></td><td>L7-01</td><td>缺知识 → RAG，缺行为 → 微调；先算清三条路线各自的成本项</td></tr><tr><td><strong>② 数据</strong></td><td>L7-02</td><td>微调的上限由数据决定，不由超参决定</td></tr><tr><td><strong>③ 训练</strong></td><td>L7-03 / L7-04</td><td>参数高效（LoRA/QLoRA）与全参分布式，两条路的资源账完全不同</td></tr><tr><td><strong>④ 对齐</strong></td><td>L7-05 / L7-06</td><td>偏好优化（DPO/ORPO/SimPO）与可验证奖励的 RL（GRPO）</td></tr><tr><td><strong>⑤ 降本</strong></td><td>L7-07 / L7-08</td><td>蒸馏换容量，量化 / 调度换成本——从显存、延迟、吞吐三个维度动手</td></tr><tr><td><strong>⑥ 多模态</strong></td><td>L7-09 / L7-10</td><td>图像是一段特殊的 token；微调 = 决定训哪一塔</td></tr></tbody></table><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>页面</th><th>覆盖知识点</th><th>学时</th><th>依赖 / 建议</th></tr></thead><tbody><tr><td>1</td><td><a href="./01-finetune-decision.html">① 微调决策：什么时候该微调</a></td><td>L7-01</td><td>3</td><td>本层入口。<strong>先读这页，再决定后面几页要不要精读</strong></td></tr><tr><td>2</td><td><a href="./02-sft-data.html">② 指令微调数据构造</a></td><td>L7-02</td><td>5</td><td>依赖 ①。数据的结构、质量判据与评测集口径同源</td></tr><tr><td>3</td><td><a href="./03-lora-and-full-finetune.html">③ LoRA / QLoRA 实操与全参微调</a></td><td>L7-03 / 04</td><td>12</td><td>依赖 ②。<strong>本层最重的实操页</strong>，大模型开发岗必精读</td></tr><tr><td>4</td><td><a href="./04-preference-and-rl.html">④ 偏好优化实战与 RL 后训练</a></td><td>L7-05 / 06</td><td>11</td><td>依赖 ③（没有 SFT 基线就谈不上对齐）。<strong>奖励信号从哪来是本页主线</strong></td></tr><tr><td>5</td><td><a href="./05-distillation-and-inference.html">⑤ 模型蒸馏与推理优化全景</a></td><td>L7-07 / 08</td><td>9</td><td>与 ③④ 并列，不互相依赖。<strong>L7-08 是本层唯一高频的降本内容</strong></td></tr><tr><td>6</td><td><a href="./06-multimodal.html">⑥ 多模态模型与多模态微调</a></td><td>L7-09 / 10</td><td>9</td><td>可放最后。<strong>L7-10 面试频率「低」</strong>，按需读</td></tr></tbody></table><p><strong>本层合计：50 学时</strong>（3 + 5 + 12 + 11 + 9 + 9 = 50）。</p><p><strong>读法建议</strong>：</p><ul><li><strong>第一遍（约 1 周，每天 2–3h）</strong>：1 → 5。<code>01</code> 页给你判据，<code>05</code> 页（尤其 L7-08）是<strong>唯一高频</strong>的降本内容，<strong>这两页必须过</strong>。</li><li><strong>第二遍（约 1 周）</strong>：2 → 3 → 4。这条线是「真要训一个模型」的完整顺序，<strong>大模型开发岗必须走完</strong>；应用岗可以只过 <code>03</code> 的「LoRA vs 全参怎么选」与 <code>04</code> 的「奖励信号从哪来」两节。</li><li><strong>只投应用岗且时间紧张</strong>：优先级 <code>01</code> &gt; <code>05</code>（L7-08 部分）&gt; <code>04</code>（奖励信号一节）&gt; 其余按需。</li><li><strong>面试前一天</strong>：只看各页的「面试怎么问」与「自检清单」，以及下面的「最容易挂在哪」。</li><li><strong>不要跳</strong>：<code>01</code> 不能跳——它是本层的判据来源，跳过它会把后面五页读成&quot;五个孤立的工具&quot;。<code>03</code> 与 <code>04</code> 的顺序不能反（偏好优化必须有一个 SFT 基线）。</li></ul><h2 id="覆盖自检表-l7-01-→-l7-10" tabindex="-1">覆盖自检表（L7-01 → L7-10） <a class="header-anchor" href="#覆盖自检表-l7-01-→-l7-10" aria-label="Permalink to &quot;覆盖自检表（L7-01 → L7-10）&quot;">​</a></h2><p><strong>10 条知识点必须全部被覆盖，且每条只出现一次</strong>（落点以各页 frontmatter 的 <code>points</code> 字段为准，可逐页核对）。</p><table tabindex="0"><thead><tr><th>☐</th><th>编号</th><th>知识点</th><th>落在哪个文件</th><th>频率</th></tr></thead><tbody><tr><td>☐</td><td>L7-01</td><td>微调决策：什么时候该微调</td><td><a href="./01-finetune-decision.html">① 微调决策</a></td><td>高</td></tr><tr><td>☐</td><td>L7-02</td><td>指令微调数据构造</td><td><a href="./02-sft-data.html">② 指令微调数据构造</a></td><td>高</td></tr><tr><td>☐</td><td>L7-03</td><td>LoRA / QLoRA 实操</td><td><a href="./03-lora-and-full-finetune.html">③ LoRA / QLoRA 实操与全参微调</a></td><td>高</td></tr><tr><td>☐</td><td>L7-04</td><td>全参数微调与分布式训练</td><td><a href="./03-lora-and-full-finetune.html">③ LoRA / QLoRA 实操与全参微调</a></td><td>中</td></tr><tr><td>☐</td><td>L7-05</td><td>偏好优化实战（DPO / ORPO / SimPO）</td><td><a href="./04-preference-and-rl.html">④ 偏好优化实战与 RL 后训练</a></td><td>中</td></tr><tr><td>☐</td><td>L7-06</td><td>强化学习后训练与 GRPO</td><td><a href="./04-preference-and-rl.html">④ 偏好优化实战与 RL 后训练</a></td><td>中</td></tr><tr><td>☐</td><td>L7-07</td><td>模型蒸馏与数据合成</td><td><a href="./05-distillation-and-inference.html">⑤ 模型蒸馏与推理优化全景</a></td><td>中</td></tr><tr><td>☐</td><td>L7-08</td><td>推理优化全景（量化 / 投机解码 / 批处理 / 分离式部署）</td><td><a href="./05-distillation-and-inference.html">⑤ 模型蒸馏与推理优化全景</a></td><td><strong>高</strong></td></tr><tr><td>☐</td><td>L7-09</td><td>多模态模型与 VLM 应用</td><td><a href="./06-multimodal.html">⑥ 多模态模型与多模态微调</a></td><td>中</td></tr><tr><td>☐</td><td>L7-10</td><td>多模态微调与拼接</td><td><a href="./06-multimodal.html">⑥ 多模态模型与多模态微调</a></td><td>低</td></tr></tbody></table><p><strong>自检结论</strong>：10 个编号 = <code>01</code>(1) + <code>02</code>(1) + <code>03</code>(2) + <code>04</code>(2) + <code>05</code>(2) + <code>06</code>(2)，<strong>不漏不重</strong>；学时合计 <strong>50h</strong>，与 <code>_specs/kb-pageplan.md</code> 第 7 节一致。<strong>频率分叉提醒</strong>：本层「高」只有 L7-01/02/03 与 L7-08 四条；L7-04/05/06/07/09 在应用岗上是「中」以下，<strong>不要在这几条上背参数</strong>。</p><h2 id="必须能画出来的图" tabindex="-1">必须能画出来的图 <a class="header-anchor" href="#必须能画出来的图" aria-label="Permalink to &quot;必须能画出来的图&quot;">​</a></h2><p>按 <code>_specs/kb-pageplan.md</code> 第 7 节对本层的要求，三张图必须能<strong>不看资料画出来</strong>——它们是这一层的骨架：</p><table tabindex="0"><thead><tr><th>#</th><th>图</th><th>画的时候必须标出的东西</th><th>对应页</th></tr></thead><tbody><tr><td>1</td><td><strong>训练三阶段流水线</strong></td><td>预训练（给知识/能力）→ SFT（给格式与指令跟随）→ 对齐（给偏好与边界）；<strong>每阶段解决什么问题、数据形态是什么</strong>；标出「微调 = 后两阶段」而不是从头训</td><td><a href="./01-finetune-decision.html">①</a> ｜ <a href="/learn/diagrams/finetuning-taxonomy.html">参考图</a></td></tr><tr><td>2</td><td><strong>LoRA 注入对比</strong></td><td>冻结的原权重 + 低秩增量两条路；增量可<strong>合并回原权重</strong>（因此推理不增延迟）；标出 <code>target_modules</code> 决定<strong>注入在哪几层</strong>、而 <code>r</code> / <code>alpha</code> 决定<strong>增量的容量</strong></td><td><a href="./03-lora-and-full-finetune.html">③</a></td></tr><tr><td>3</td><td><strong>微调全流程数据管线</strong></td><td>采集 → 清洗 → 去重 → 格式转换（chat template）→ 长度与 loss 掩码 → 划分 → 训练 → <strong>评测与回归关卡</strong>；<strong>标出&quot;每一步错了后面修不回来&quot;的位置</strong></td><td><a href="./02-sft-data.html">②</a></td></tr></tbody></table><p>另外四张是各页的主图，能画出来说明那一页真读懂了：</p><table tabindex="0"><thead><tr><th>#</th><th>图</th><th>必须标出的东西</th><th>对应页</th></tr></thead><tbody><tr><td>4</td><td><strong>后训练完整顺序与奖励信号谱系</strong></td><td>SFT → 偏好优化 →（可选）RL 后训练的顺序；以及「奖励从哪来」的谱系：人工标注 / 偏好评判模型 / <strong>可验证奖励</strong></td><td><a href="./04-preference-and-rl.html">④</a></td></tr><tr><td>5</td><td><strong>推理优化三维决策树</strong></td><td>显存 / 延迟 / 吞吐三个入口；每个手段<strong>优化哪一维、代价是什么</strong>；Prefill 算力密集 vs Decode 访存密集</td><td><a href="./05-distillation-and-inference.html">⑤</a> ｜ <a href="/learn/diagrams/llm-inference-pipeline.html">参考图</a></td></tr><tr><td>6</td><td><strong>VLM 三段式结构</strong></td><td>视觉编码器 → 投影层 → 语言模型；<strong>&quot;图像只是一段特殊 token&quot;</strong>；视觉 token 同时影响成本、上下文、显存</td><td><a href="./06-multimodal.html">⑥</a></td></tr><tr><td>7</td><td><strong>文档理解的分级处理</strong></td><td>先便宜的文本抽取 → 只在&quot;抽取不可靠&quot;或&quot;内容本身是视觉的&quot;（图/表/公式）时才走视觉；<strong>视觉调用只覆盖必要区域</strong></td><td><a href="./06-multimodal.html">⑥</a></td></tr></tbody></table><blockquote><p>图库里本层已交付的参考图：<a href="/learn/diagrams/finetuning-taxonomy.html">训练与微调方法分类</a>、<a href="/learn/diagrams/llm-inference-pipeline.html">LLM 推理管线</a>。全部：<a href="/learn/diagrams/">/diagrams/</a></p></blockquote><h2 id="这一层最容易挂在哪" tabindex="-1">这一层最容易挂在哪 <a class="header-anchor" href="#这一层最容易挂在哪" aria-label="Permalink to &quot;这一层最容易挂在哪&quot;">​</a></h2><p>按「<strong>被问到的概率 × 答不出来的代价</strong>」排序：</p><p><strong>1）报出框架的参数名、默认值或模型规格（全层，尤其 ③④）。</strong> 这是本层<strong>最快也最致命</strong>的失分方式。<code>r</code> / <code>alpha</code> / <code>target_modules</code> 没有普适最优值（<strong>必须在自己验证集上扫</strong>），QLoRA 的量化配置项、DeepSpeed 各 ZeRO stage 的开关名、DPO/ORPO/SimPO 的超参、GRPO 的实现细节、各家模型的参数量与上下文长度——<strong>都在持续变动，且各框架命名不同</strong>。正确答法是<strong>只讲机制与取舍方向</strong>，加上一句「<strong>具体参数名与默认值以官方文档为准</strong>」。<strong>答&quot;我记得是……&quot;比答&quot;我不背这个，我查文档&quot;危险得多</strong>——后者是工程习惯，前者是风险敞口。</p><p><strong>2）把 LoRA 的 <code>r</code> 当成&quot;越大越好&quot;的旋钮（③ L7-03）。</strong> <code>r</code> 决定低秩增量的容量：<strong>越大越能表达、也越容易过拟合且显存与训练时间上升</strong>；<code>alpha</code> 是缩放系数，通常和 <code>r</code> 一起被讨论；<code>target_modules</code> 决定<strong>注入到哪些层</strong>——<strong>这三个是三个不同的问题，混在一起谈就说明没实际跑过</strong>。安全答法：给「常见区间」+ 一句「<strong>无普适最优，要在验证集上扫</strong>」+ 说明你会用哪个指标判断。</p><p><strong>3）「SFT 效果不好 → 加数据、加 epoch」（② L7-02）。</strong> 微调的上限由<strong>数据</strong>决定，不由超参决定：<strong>格式不一致、长度分布失控（静默截断）、训练集与评测集泄漏</strong>这三类问题，加再多轮数也修不回来，只会<strong>把错误记得更牢</strong>。必须能说出「先看哪几个指标判断是数据问题还是超参问题」。</p><p><strong>4）把&quot;训得更多&quot;当默认方向（④ L7-06 / ⑤ L7-07）。</strong> 两个高频错误：<strong>一是没有可靠的评测就去做后训练</strong>——偏好优化需要一个能判&quot;哪个回答更好&quot;的信号，<strong>没有可信的评测，奖励信号就是噪声，训练只会把噪声固化进权重</strong>；<strong>二是以为&quot;蒸馏就是让学生超过老师&quot;</strong>——学生通常只是在<strong>特定任务与成本约束下更有性价比</strong>，能超过老师的只有三种例外情况（教师通用而学生专用 / 教师受约束没发挥 / 学生用了教师之外的信息）。</p><p><strong>5）用推理侧的思路解决训练侧的问题，或者反过来（① L7-01 / ⑤ L7-08）。</strong> 两条典型错法：<strong>「知识不够 → 去微调」</strong>（时效性知识应该走 RAG，微调更适合改<strong>输出格式与行为风格</strong>）；<strong>「延迟高 → 换个更快的模型」</strong>（先拆时间构成——常见的真实情况是瓶颈根本不在模型生成，而在检索或前置计算上）。<strong>判据：先定位瓶颈在哪一环，再谈手段。</strong></p><h2 id="本层必须记住的项目口径" tabindex="-1">本层必须记住的项目口径 <a class="header-anchor" href="#本层必须记住的项目口径" aria-label="Permalink to &quot;本层必须记住的项目口径&quot;">​</a></h2><p>这一层的每一页都有一节「和你自己的项目对上号」，<strong>共同前提只有一条，必须先说清楚</strong>：</p><blockquote><p><strong>两个项目都没有做过任何训练。</strong> 全程只用了推理侧的现成模型——Embedding 用 <code>bge-m3</code>、Reranker 用 <code>bge-reranker-v2-m3</code>、生成走 OpenAI 兼容协议的 <code>deepseek-flash</code> / <code>deepseek-v4-pro</code>。<strong>没有训过生成模型、没有训过 Embedding / Reranker、没有做过偏好优化、没有做过量化或推理优化、没有用过多模态模型。</strong></p></blockquote><p>被问到时该用的口径（<strong>如实 + 有判据</strong>，不是回避）：</p><table tabindex="0"><thead><tr><th>口径</th><th>数字 / 说法</th><th>用在哪页</th></tr></thead><tbody><tr><td>语料规模</td><td><strong>55 篇 / 5325 块</strong>；切块两档（<code>&quot;512&quot;</code> 档实际 <code>max_chars</code> <strong>1024</strong> / overlap <strong>153</strong>；<code>&quot;1024&quot;</code> 档 <strong>2048 / 307</strong>）</td><td>① ② ⑥</td></tr><tr><td>检索质量</td><td>三档 R@5 <strong>64.4% / 59.1% / 71.8%</strong>；MRR <strong>0.502 → 0.714</strong>（混合+精排 vs 混合无精排，差 <strong>12.7 pp</strong>）</td><td>① ③ ⑤</td></tr><tr><td>延迟构成</td><td>端到端 P50 <strong>15.66 s</strong>（检索 <strong>14.47 s</strong> / 生成 <strong>1.26 s</strong>，<strong>约 92% 在检索侧</strong>）；精排 20 对约 <strong>8.5 s</strong>（CPU）；冷启动 <strong>67.3 s</strong></td><td>⑤ ⑥</td></tr><tr><td>成本信号</td><td>缓存命中与未命中<strong>差约 50 倍</strong>（<code>deepseek-flash</code> in_hit 0.006 vs in_miss 0.30 美元/百万 token）</td><td>⑤</td></tr><tr><td>评测纪律</td><td>Gate-1：<strong>40 题 × 2 臂配对</strong>，完成率差 +0.025（<strong>NSC</strong>）、墙钟 2.11×（<strong>REGRESSION</strong>）；<strong>两个检验必须同向显著才算数</strong></td><td>④</td></tr><tr><td>为什么先不微调</td><td><strong>Reranker &gt; Embedding &gt; 生成模型</strong> 是候选排序；而 RAG 的瓶颈在<strong>检索侧</strong>，且生成侧走 API <strong>没有权重</strong>，全参微调不在选项里</td><td>① ③</td></tr></tbody></table><p><strong>两句可以背下来的定位</strong>：</p><ul><li>「<strong>我不是没做微调，我是先用 40 题配对检验证明了改动是否有效——在没有可信评测之前，做后训练只会把噪声固化进权重。</strong>」</li><li>「<strong>我的系统里 92% 的延迟在检索侧，所以&#39;优化模型推理&#39;对我是选错了维度。</strong>」</li></ul><h2 id="两条未验证事项-必须如实说" tabindex="-1">两条未验证事项（必须如实说） <a class="header-anchor" href="#两条未验证事项-必须如实说" aria-label="Permalink to &quot;两条未验证事项（必须如实说）&quot;">​</a></h2><ol><li><p><strong>本层全部 6 页都不含训练或推理优化的实测。</strong> 页内出现的所有机制说明、决策树、参数取舍方向都是<strong>依据公开资料与原理推导</strong>，<strong>没有在本机跑过任何一次微调、偏好优化、蒸馏、量化或视觉模型调用</strong>。因此本层<strong>不提供任何&quot;调完之后的数字&quot;</strong>——凡是要报效果的地方，验收方式都写在对应页末尾的「未执行验证」注释里（统一形状是：<strong>先用评测集定义成功判据，再谈训练</strong>）。</p></li><li><p><strong>各框架的具体参数名、默认值与模型规格一律未在本地快照中确证。</strong> <code>LLaMA-Factory</code> / <code>ms-swift</code> / <code>PEFT</code> / <code>TRL</code> / <code>DeepSpeed</code> / <code>vLLM</code> 的字段名、各模型的参数量与层数、视觉 token 的换算方式、Chinchilla 系数——<strong>页内凡涉及这些的地方都标注了「以官方文档为准」</strong>。这不是偷懒：<strong>这一层的知识时效性在所有层里最高</strong>，把会变的东西背下来，是最快失效的投入。</p></li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>上层原理（本层只做一句话回顾的地方在这里）：<a href="/learn/kb/l1-llm/">L1 · 大模型原理</a>——<a href="/learn/kb/l1-llm/08-sft-and-lora.html">SFT 与 LoRA 原理</a> ｜ <a href="/learn/kb/l1-llm/10-alignment-rlhf-dpo.html">RLHF 与 DPO 原理</a> ｜ <a href="/learn/kb/l1-llm/11-kv-cache-and-inference.html">KV Cache 与推理</a></li><li>上线与成本（L7-08 的工程侧）：<a href="/learn/kb/l5-engineering/">L5 · 工程化</a>——<a href="/learn/kb/l5-engineering/06-inference-serving.html">推理服务化</a></li><li>评测（做任何后训练之前必须先有的东西）：<a href="/learn/kb/l6-eval-observability/">L6 · 评测与可观测性</a></li><li>前置层：<a href="/learn/kb/l0-foundation/">L0</a> ｜ <a href="/learn/kb/l2-prompt/">L2 提示工程</a> ｜ <a href="/learn/kb/l3-rag/">L3 RAG</a> ｜ <a href="/learn/kb/l4-agent/">L4 Agent</a></li><li>项目实证：<a href="/learn/projects/rag/">科研文献 RAG</a> ｜ <a href="/learn/projects/yyhelp/11-evaluation.html">YYHelp 评测与 A/B 显著性</a></li><li>面试专项：<a href="/learn/interview/llm.html">大模型面试题库</a> ｜ <a href="/learn/interview/cheatsheet.html">速查表</a></li><li>图库：<a href="/learn/diagrams/">/diagrams/</a></li></ul>',42)])])}const m=r(n,[["render",a]]);export{p as __pageData,m as default};
